import React, { useState } from 'react';
import Background from '../components/Background';
import MeshSphere from '../components/MeshSphere';
import { useMoods } from '../hooks/useStorage';

const MOODS = [
  { score:1, emoji:'😔', label:'Väldigt dåligt', sub:'Det är tungt just nu',  mood:'heavy', speed:0.15, distort:1.6,
    grad:'linear-gradient(135deg, rgba(210,170,170,0.85) 0%, rgba(195,165,185,0.8) 100%)' },
  { score:2, emoji:'😟', label:'Dåligt',         sub:'Lite tyngd idag',       mood:'warm',  speed:0.2, distort:1.2,
    grad:'linear-gradient(135deg, rgba(215,185,165,0.85) 0%, rgba(205,180,190,0.8) 100%)' },
  { score:3, emoji:'😐', label:'Okej',           sub:'Varken bra eller dåligt', mood:'default', speed:0.4, distort:0.7,
    grad:'linear-gradient(135deg, rgba(195,190,215,0.85) 0%, rgba(205,195,210,0.8) 100%)' },
  { score:4, emoji:'🙂', label:'Bra',            sub:'Det känns ganska bra',  mood:'calm', speed:0.6, distort:0.45,
    grad:'linear-gradient(135deg, rgba(175,200,215,0.85) 0%, rgba(185,205,220,0.8) 100%)' },
  { score:5, emoji:'😄', label:'Väldigt bra',    sub:'I ett riktigt flow',    mood:'flow', speed:0.85, distort:0.2,
    grad:'linear-gradient(135deg, rgba(175,210,200,0.85) 0%, rgba(185,215,210,0.8) 100%)' },
];

export default function CheckIn({ setPage }) {
  const { addMood, todayChecked } = useMoods();
  const [hovered,  setHovered]    = useState(null);
  const [selected, setSelected]   = useState(null);
  const [note,     setNote]       = useState('');
  const [step,     setStep]       = useState('pick');

  const activeIdx  = hovered ?? selected ?? 2;
  const activeMood = MOODS[activeIdx];

  const handleSave = () => {
    const m = MOODS[selected];
    addMood(m.score, m.emoji, m.label, note);
    setStep('done');
  };

  if (todayChecked && step !== 'done') return (
    <DoneScreen mood={MOODS[2]} title="Redan incheckad" sub="Kom tillbaka imorgon." setPage={setPage} />
  );
  if (step === 'done') return (
    <DoneScreen mood={MOODS[selected]} title="Sparat ✓" sub="Bra jobbat att du checkade in." setPage={setPage} />
  );

  if (step === 'note') return (
    <div style={{ minHeight:'100vh', paddingTop:56, paddingBottom:96, position:'relative' }}>
      <Background mood={MOODS[selected].mood} />
      <div style={{ position:'relative', zIndex:1, padding:'28px 22px', maxWidth:480, margin:'0 auto', animation:'fadeUp .5s cubic-bezier(0.16,1,0.3,1) both' }}>
        <div style={{ display:'flex', justifyContent:'center', marginBottom:24 }}>
          <MeshSphere size={200} speed={MOODS[selected].speed} distort={MOODS[selected].distort} key={selected} />
        </div>
        <div style={{ textAlign:'center', marginBottom:28 }}>
          <span style={{ fontSize:40, display:'block', marginBottom:8 }}>{MOODS[selected].emoji}</span>
          <h2 style={{ fontSize:28, fontWeight:700, letterSpacing:'-0.03em', color:'#1c1917', marginBottom:4 }}>{MOODS[selected].label}</h2>
          <p style={{ fontSize:13, color:'rgba(28,25,23,0.45)', fontWeight:300 }}>{MOODS[selected].sub}</p>
        </div>
        <div style={{ background:'rgba(255,255,255,0.7)', borderRadius:20, padding:'16px 18px', marginBottom:12, backdropFilter:'blur(16px)', border:'1px solid rgba(255,255,255,0.9)', boxShadow:'0 2px 12px rgba(0,0,0,0.05)' }}>
          <p style={{ fontSize:12, color:'rgba(28,25,23,0.4)', fontWeight:500, textTransform:'uppercase', letterSpacing:'0.04em', marginBottom:10 }}>Valfri notering</p>
          <textarea value={note} onChange={e=>setNote(e.target.value)} maxLength={255}
            placeholder="Vad hände idag? Hur kändes det?"
            style={{ width:'100%', background:'transparent', border:'none', color:'#1c1917', fontSize:15, fontWeight:300, resize:'none', height:88, outline:'none', lineHeight:1.75 }} />
        </div>
        <button onClick={handleSave} style={{ width:'100%', padding:'15px', borderRadius:100, background:'#1c1917', color:'#f0ece6', fontSize:14, fontWeight:600, marginBottom:10, boxShadow:'0 4px 20px rgba(0,0,0,0.18)', border:'none' }}>
          Spara →
        </button>
        <button onClick={()=>setStep('pick')} style={{ width:'100%', padding:'10px', fontSize:13, color:'rgba(28,25,23,0.38)', fontWeight:400 }}>
          ← Ändra humör
        </button>
      </div>
    </div>
  );

  return (
    <div style={{ minHeight:'100vh', paddingTop:56, paddingBottom:96, position:'relative' }}>
      <Background mood={activeMood.mood} />
      <div style={{ position:'relative', zIndex:1, padding:'24px 22px', maxWidth:480, margin:'0 auto' }}>

        {/* Sphere — changes with hover */}
        <div style={{ display:'flex', justifyContent:'center', marginBottom:24, animation:'fadeIn .8s ease both' }}>
          <MeshSphere size={240} speed={activeMood.speed} distort={activeMood.distort} key={activeIdx} />
        </div>

        <div style={{ marginBottom:24, animation:'fadeUp .7s .1s both' }}>
          <p style={{ fontSize:12, color:'rgba(28,25,23,0.4)', fontWeight:500, textTransform:'uppercase', letterSpacing:'0.04em', marginBottom:8 }}>Daglig check-in</p>
          <h1 style={{ fontSize:'clamp(30px,7vw,46px)', fontWeight:700, letterSpacing:'-0.04em', lineHeight:1.05, color:'#1c1917' }}>
            Hur mår du<br/><span style={{ fontStyle:'italic', fontWeight:300, color:'rgba(28,25,23,0.45)' }}>idag?</span>
          </h1>
        </div>

        {/* Mood cards — gradient like Light app */}
        <div style={{ display:'flex', flexDirection:'column', gap:8, marginBottom:16, animation:'fadeUp .7s .15s both' }}>
          {MOODS.slice().reverse().map((m, i) => {
            const idx = 4 - i;
            const isSel = selected === idx;
            const isHov = hovered === idx;
            return (
              <button key={m.score}
                onMouseEnter={()=>setHovered(idx)} onMouseLeave={()=>setHovered(null)}
                onClick={()=>setSelected(idx)}
                style={{ display:'flex', alignItems:'center', gap:14, padding:'14px 18px', borderRadius:18, background: isSel||isHov ? m.grad : 'rgba(255,255,255,0.55)', border:`1px solid ${isSel ? 'rgba(255,255,255,0.95)' : 'rgba(255,255,255,0.75)'}`, backdropFilter:'blur(12px)', boxShadow: isSel ? '0 4px 20px rgba(0,0,0,0.1)' : '0 1px 6px rgba(0,0,0,0.04)', transition:'all .25s cubic-bezier(0.16,1,0.3,1)', transform: isHov&&!isSel ? 'translateX(4px)' : 'none' }}>
                <span style={{ fontSize:26, flexShrink:0, transition:'transform .2s', transform: isHov||isSel ? 'scale(1.12)' : 'scale(1)' }}>{m.emoji}</span>
                <div style={{ flex:1, textAlign:'left' }}>
                  <div style={{ fontSize:15, fontWeight: isSel ? 600 : 400, color:'#1c1917', letterSpacing:'-0.01em', transition:'font-weight .2s' }}>{m.label}</div>
                  <div style={{ fontSize:12, color:'rgba(28,25,23,0.45)', marginTop:1, fontWeight:300 }}>{m.sub}</div>
                </div>
                {(isSel||isHov) && <span style={{ fontSize:14, color:'rgba(28,25,23,0.4)' }}>→</span>}
              </button>
            );
          })}
        </div>

        <button onClick={()=>setStep('note')} disabled={selected===null}
          style={{ width:'100%', padding:'15px', borderRadius:100, background:selected!==null?'#1c1917':'rgba(0,0,0,0.08)', color:selected!==null?'#f0ece6':'rgba(28,25,23,0.3)', fontSize:14, fontWeight:600, transition:'all .3s', border:'none', boxShadow:selected!==null?'0 4px 20px rgba(0,0,0,0.18)':'none' }}>
          Fortsätt →
        </button>
      </div>
    </div>
  );
}

function DoneScreen({ mood, title, sub, setPage }) {
  return (
    <div style={{ minHeight:'100vh', paddingTop:56, paddingBottom:96, display:'flex', flexDirection:'column', alignItems:'center', justifyContent:'center', padding:'80px 22px', position:'relative' }}>
      <Background mood={mood.mood} />
      <div style={{ position:'relative', zIndex:1, textAlign:'center' }}>
        <div style={{ display:'flex', justifyContent:'center', marginBottom:24 }}>
          <MeshSphere size={200} speed={mood.speed} distort={mood.distort} />
        </div>
        <h2 style={{ fontSize:32, fontWeight:700, letterSpacing:'-0.04em', color:'#1c1917', marginBottom:8 }}>{title}</h2>
        <p style={{ fontSize:15, color:'rgba(28,25,23,0.5)', marginBottom:36, fontWeight:300 }}>{sub}</p>
        <div style={{ display:'flex', gap:10, justifyContent:'center' }}>
          <button onClick={()=>setPage('history')} style={{ padding:'13px 24px', borderRadius:100, background:'#1c1917', color:'#f0ece6', fontSize:13, fontWeight:600, boxShadow:'0 4px 20px rgba(0,0,0,0.18)', border:'none' }}>Se historik</button>
          <button onClick={()=>setPage('home')} style={{ padding:'13px 24px', borderRadius:100, background:'rgba(255,255,255,0.65)', border:'1px solid rgba(255,255,255,0.85)', color:'rgba(28,25,23,0.65)', fontSize:13, backdropFilter:'blur(12px)' }}>Hem</button>
        </div>
      </div>
    </div>
  );
}
